tool_input.command:
cd /private/tmp/100-tricks-runs/pilot-hard/without/h2-eval-thresholds/r3 && node -e '
const fs = require("fs");
const anchor = "- `--format <json|markdown>` – output format (defaults to JSON). Markdown reports include human-readable summaries for review boards.\n";
const addition = "- `--threshold <metric>=<min>` – fail the run when a metric scores below `min` (0 to 1); repeat for several metrics, e.g. `--threshold exact_match=0.9 --threshold toxicity=1`. Exits 1 if any threshold fails (including metrics with no score, such as exact match without references) and 0 if all pass; the report is written either way with a top-level `passed` flag and a `thresholds` list (Markdown reports get a Thresholds section). A malformed threshold or unknown metric id exits 2 without writing a report. SDK users can pass `thresholds: { exact_match: 0.9 }` to `Eval.generateReport`, which also works for custom metrics.\n";
for (const file of ["README.md", "packages/frai-cli/README.md", "packages/frai-core/README.md"]) {
  const text = fs.readFileSync(file, "utf8");
  if (text.split(anchor).length !== 2) throw new Error("anchor not unique in " + file);
  fs.writeFileSync(file, text.replace(anchor, anchor + addition));
}
' && git diff --stat -- '*.md'
